import React from 'react'
import './sb.css'; 

const NewsItem = (props)=> {
       const stars = Array.from({ length: 100 }, (_, i) => <div key={i} className="star"></div>);
        let { title, description, imageUrl, newsUrl, author, date, source } = props;
        return (
            <div className="stars-container">
                {stars}
                <div className="card" >
                    <div style={{
                        display: 'flex',
                        justifyContent: 'flex-end',
                        position: 'absolute',
                        right: '0'
                    }
                    }> 
                        <span className="badge rounded-pill bg-danger"> {source} </span>
                    </div>
                    <img src={!imageUrl ? "https://images.unsplash.com/photo-1521747116042-5a810fda9664" : imageUrl} style={{height: '260px'}}className="card-img-top" alt="..." />
                    <div className="card-body">
                        <h5 className="card-title">{title}  </h5>
                        <p className="card-text">{description.slice(0, 70)}</p>
                        <p className="card-text"><small className="text-muted">By {!author ? "Unknown" : author} on  {new Date(date).toGMTString()}</small></p>
                        <a rel="noreferrer" href={newsUrl} target="_blank" className="btn btn-sm btn-dark">Read More</a>
                    </div>
                </div>
            </div>
        )

}

export default NewsItem
